sys_script_include.script:
var HoCOHSMACLUtils = Class.create();
HoCOHSMACLUtils.prototype = {
    initialize: function() {},

    checkUserWriteForCommitteeSection: function(userId, current) {
        var result = false;
        var allowedRoles = "x_hccc_hoc_ohs.committee,x_hccc_hoc_ohs.advisor";

        if (gs.hasRole(allowedRoles))
            result = true;
        return result;



    },


    checkUserWriteForManagerSection: function(userId, current) {

        var allowedRoles = "x_hccc_hoc_ohs.advisor";
        if (gs.hasRole(allowedRoles) || userId == current.manager_name.toString())
            result = true;
        return result;


    },
    type: 'HoCOHSMACLUtils'
};
